    commitGame(() => next);
    setBlueprintPlacementId(blueprintId);
    setPlacement(null);
    setSelectionMode(false);
    setDeleteMode(false);
    setRegionMode(false);
    setNotice(`已复制 ${eligibleIds.length} 个设备，点击画布粘贴蓝图`);
